def fill_between(grid, fill_color, marker, new_color, min_markers=3):
    """Between consecutive marker cells in any row or column (line holding at least min_markers markers), a run of fill_color cells becomes new_color."""
    H,W=len(grid),len(grid[0])
    r=[row[:] for row in grid]
    lines=[[(i,j) for j in range(W)] for i in range(H)]+[[(i,j) for i in range(H)] for j in range(W)]
    for line in lines:
        idx=[k for k,(i,j) in enumerate(line) if grid[i][j]==marker]
        if len(idx)<max(2,min_markers): continue
        for a,b in zip(idx,idx[1:]):
            if all(grid[line[k][0]][line[k][1]]==fill_color for k in range(a+1,b)):
                for k in range(a+1,b): r[line[k][0]][line[k][1]]=new_color
    return r


